// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0));
        vm.assume(addr1 != addr2);

        // Get totalSupply before call
        uint256 totalSupplyBefore = c.totalSupply();

        // Get balances of both addresses
        uint256 balance1 = c.balanceOf(addr1);
        uint256 balance2 = c.balanceOf(addr2);

        // Call allowance (this is the function that triggers the bug)
        c.allowance(addr1, addr2);

        // Get totalSupply after call
        uint256 totalSupplyAfter = c.totalSupply();

        // Get balances after
        uint256 balance1After = c.balanceOf(addr1);
        uint256 balance2After = c.balanceOf(addr2);

        // Total supply must equal sum of all balances (at least these two accounts)
        // Since we can't enumerate all accounts, we check that totalSupply didn't change
        // while balances didn't change either
        assertTrue(totalSupplyBefore == totalSupplyAfter && balance1 == balance1After && balance2 == balance2After);
    }
}

