// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address owner, address spender) public {
        vm.assume(owner != address(0) && spender != address(0));
        vm.assume(spender != address(c));

        // Trigger the allowance call
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.allowance.selector, owner, spender));
        require(success, "allowance call failed");

        // Check general rule: totalSupply must be <= sum of all balances
        // Since we can't enumerate all addresses, we use a simpler invariant:
        // totalSupply should be non-negative and equal to itself (trivially true)
        // This is not a useful invariant, so we need a different approach

        // Better: totalSupply must be >= any single balance we can observe
        address someAddr = address(this);
        uint256 someBalance = c.balanceOf(someAddr);
        uint256 total = c.totalSupply();

        // After allowance, totalSupply should be >= balanceOf(this) (a basic invariant)
        assertTrue(total >= someBalance);
    }
}

