pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        amount1 = bound(amount1, 1, 1e30);
        amount2 = bound(amount2, 1, 1e30);
        // Transfer tokens to the contract via mint (by calling approveAndCall indirectly)
        // We'll use direct state manipulation via prank to simulate transfers
        // Instead, we drive through public interface: mint via transferFrom
        // Since there is no mint accessible, we use the burnFrom/burn path: first mint by exploiting approveAndCall
        // Simpler: just ensure we have some totalSupply by calling burn and seeing if balanceOf changes
        // Use allowance call as required
        c.approve(addr1, amount1);
        c.approve(addr2, amount2);
        // The main action: call allowance to trigger the bug
        c.allowance(addr1, addr2);
        // Now compute totalSupply from public getter
        uint256 ts = c.totalSupply();
        // We cannot enumerate all addresses, but we can check that totalSupply is at most the sum of known balances
        // Use a known address: this contract's address itself (might have balance from mint or transfer)
        uint256 sumBalances = c.balanceOf(address(0)) + c.balanceOf(address(this)) + c.balanceOf(addr1) + c.balanceOf(addr2);
        assertTrue(ts == sumBalances, "totalSupply != sum of balances");
    }
}

