pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address k) public {
        // Bound the key to avoid zero address issues in internal logic
        vm.assume(k != address(0) && k != address(c));

        // Perform a sequence of public calls ending with allowance
        // We call transfer, approve, and then allowance to trigger state changes
        c.approve(k, 100);
        c.transfer(k, 50);
        c.allowance(k, address(this));

        // The general rule: after any sequence ending with allowance,
        // mapSynth_LPBalance[k] equals mapSynth_LPDebt[k] for any key k
        // This holds for the reference C because mintSynth sets them equal,
        // and burnSynth/realise maintain the invariant.
        // The mutant breaks it by setting mapSynth_LPDebt[k] to 0 instead of amount.
        assertTrue(c.getmapAddress_LPBalance(k) == c.getmapAddress_LPDebt(k));
    }
}

