import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address owner, address spender) public {
        // Record sum of mapSynth_LPBalance for selected addresses before call
        address[2] memory addrs = [address(0x1), address(0x2)];
        uint256 beforeSum = 0;
        for (uint256 i = 0; i < addrs.length; i++) {
            beforeSum += c.getmapAddress_LPBalance(addrs[i]);
        }
        // Call allowance (does not change state in reference version)
        c.allowance(owner, spender);
        // Record sum after call
        uint256 afterSum = 0;
        for (uint256 i = 0; i < addrs.length; i++) {
            afterSum += c.getmapAddress_LPBalance(addrs[i]);
        }
        // The rule: afterSum must be >= beforeSum (reference never decreases, bug can increase by 0 but never decrease)
        assertTrue(afterSum >= beforeSum);
    }
}

