pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address pool1, address pool2, uint256 lpBal1, uint256 lpBal2, uint256 debt1, uint256 debt2) public {
        // Bound inputs to avoid overflow and allow meaningful state
        lpBal1 = bound(lpBal1, 0, 1e30);
        lpBal2 = bound(lpBal2, 0, 1e30);
        debt1 = bound(debt1, 0, 1e30);
        debt2 = bound(debt2, 0, 1e30);

        // Set up state by directly writing to storage via prank (only possible through constructor or public functions)
        // Since we can't write to mapSynth_LPBalance or mapSynth_LPDebt directly, we use prank as pool to call realise
        // But we need to first mint some LP tokens to c and create debt. Use the public surface:
        // We can't call mintSynth because onlyPool modifier requires curated pool.
        // So we simulate by calling getters to compute invariant after allowance.

        // Instead, we use the fact that allowance does not change state.
        // The invariant is about the relationship between LP balances and debts after any operation.
        // To test the mutant, we need to set state where premium < 1e18 but baseValueLP > baseValueSynth.
        // We can do this by calling realise with state set via vm.store (cheatcode) before the test.

        // Store values for two pools
        vm.store(address(c), keccak256(abi.encode(pool1, uint256(4))), bytes32(lpBal1)); // slot for mapSynth_LPBalance mapping
        vm.store(address(c), keccak256(abi.encode(pool1, uint256(5))), bytes32(debt1)); // slot for mapSynth_LPDebt mapping
        vm.store(address(c), keccak256(abi.encode(pool2, uint256(4))), bytes32(lpBal2));
        vm.store(address(c), keccak256(abi.encode(pool2, uint256(5))), bytes32(debt2));

        // Call allowance to trigger the bug check
        c.allowance(address(0), address(0));

        // Compute total LP balance for pools with positive debt
        uint256 totalLP = 0;
        uint256 totalDebt = 0;
        if (c.getmapAddress_LPDebt(pool1) > 0) {
            totalLP += c.getmapAddress_LPBalance(pool1);
            totalDebt += c.getmapAddress_LPDebt(pool1);
        }
        if (c.getmapAddress_LPDebt(pool2) > 0) {
            totalLP += c.getmapAddress_LPBalance(pool2);
            totalDebt += c.getmapAddress_LPDebt(pool2);
        }

        // The invariant: total LP covering debt should be >= total debt (since realise only reduces LP when premium >= 1e18)
        // But the mutant reduces LP even when premium < 1e18, breaking this.
        assertTrue(totalLP >= totalDebt);
    }
}

