        // Actually, the token's name is iBEP20(address(this)).name(), which in test is not a token.
        // So we use a general rule: for any token that returns a non-empty name, the synth name starts with that name.
        // Since we can't get token name directly from address(this), we check that the name contains "SpartanProtocolSynthetic"
        string memory suffix = "-SpartanProtocolSynthetic";
        uint suffixLen = bytes(suffix).length;
        uint nameLen = bytes(nameResult).length;
        bool endsCorrectly;
        if (nameLen >= suffixLen) {
            endsCorrectly = keccak256(abi.encodePacked(slice(nameResult, nameLen - suffixLen, suffixLen))) == keccak256(abi.encodePacked(suffix));
        }
        assertTrue(endsCorrectly);
    }

    function slice(string memory str, uint startIndex, uint length) internal pure returns (string memory) {
        bytes memory strBytes = bytes(str);
        require(startIndex + length <= strBytes.length);
        bytes memory result = new bytes(length);
        for (uint i = 0; i < length; i++) {
            result[i] = strBytes[startIndex + i];
        }
        return string(result);
    }
}

