pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(string memory tokenSymbol) public {
        // Bound the input to avoid unrealistic strings
        vm.assume(bytes(tokenSymbol).length > 0 && bytes(tokenSymbol).length < 32);

        // Deploy a mock token with the given symbol
        // We'll use a simple approach: set the token's symbol via its public getter
        // But C expects the TOKEN address to have a name() and symbol() that return strings
        // We can use a minimal mock that we deploy here
        MockToken token = new MockToken(tokenSymbol);

        // Deploy C with the mock token as the LayerONE (TOKEN)
        C c2 = new C(address(this), address(token));

        // Call symbol() and check it ends with the expected suffix
        string memory returnedSymbol = c2.symbol();
        string memory expectedSuffix = "-SPS";

        // Check that the returned symbol is not the hardcoded "MUTATED_SYMBOL"
        // and that it ends with the expected suffix
        bytes memory returnedBytes = bytes(returnedSymbol);
        bytes memory expectedSuffixBytes = bytes(expectedSuffix);

        // Assert that the returned symbol ends with the suffix
        bool endsWithSuffix = true;
        uint256 offset = returnedBytes.length - expectedSuffixBytes.length;
        for (uint256 i = 0; i < expectedSuffixBytes.length; i++) {
            if (returnedBytes[offset + i] != expectedSuffixBytes[i]) {
                endsWithSuffix = false;
                break;
            }
        }

        // Also check it doesn't equal the hardcoded mutant value
        string memory mutatedSymbol = "MUTATED_SYMBOL";
        bool notMutated = keccak256(bytes(returnedSymbol)) != keccak256(bytes(mutatedSymbol));

        assertTrue(endsWithSuffix && notMutated, "symbol should end with -SPS and not be hardcoded");
    }
}

// Minimal ERC20-like token for testing
contract MockToken {
    string private _symbol;
    constructor(string memory symbol_) { _symbol = symbol_; }
    function name() external view returns (string memory) { return _symbol; }
    function symbol() external view returns (string memory) { return _symbol; }
    function decimals() external view returns (uint8) { return 18; }
}

